{"category_edits":[{"category":"training_strategy","rationale":"Implement the requested learning-rate schedule explicitly for all four category models: halve the rate after two consecutive validation checks without a new best HR@10, with a floor of one-eighth the initial rate. Preserve all other training settings, model structure, loss, early stopping, and prediction behavior.","edits":[{"find":"    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
        optimizer, mode="max", factor=0.5, patience=1,
        threshold=0.0, threshold_mode="abs", min_lr=LR * 0.125
    )","replace":"    lr_plateau_checks = 0"},{"find":"            scheduler.step(hr10)","replace":"            if hr10 > best_hr10:
                lr_plateau_checks = 0
            else:
                lr_plateau_checks += 1
                if lr_plateau_checks >= 2:
                    for param_group in optimizer.param_groups:
                        param_group["lr"] = max(param_group["lr"] * 0.5, LR * 0.125)
                    lr_plateau_checks = 0"}]}],"change_summary":"Make the two-check plateau schedule explicit, enforcing the exact learning-rate floor without the scheduler's default numerical epsilon."}
